TYPE.TEST:


SetFunctionName("VecAbs");
using namespace ::rw::math::vpl;

VectorIntrinsic  v0 = CreateVectorIntrinsic(1.0f, -2.0f,  3.0f,  -4.0f);
VectorIntrinsic ref = CreateVectorIntrinsic(1.0f,  2.0f,  3.0f,   4.0f);
VectorIntrinsic   r = VecAbs(v0);
Validate( IsEqualFloat(r,ref) );



SetFunctionName("VecAdd");
