SetFunctionName("VecAnyTrue_Word");
using namespace ::rw::math::vpl;

VectorIntrinsic testA = CreateVectorIntrinsic(0x00000000U, 0xffffffffU, 0xffffffffU, 0x00000000U);
VectorIntrinsic testB = CreateVectorIntrinsic(0x00000000U, 0xffffffffU, 0x00000000U, 0x00000000U);
VectorIntrinsic testC = CreateVectorIntrinsic(0xffffffffU, 0xffffffffU, 0xffffffffU, 0xffffffffU);
VectorIntrinsic testD = CreateVectorIntrinsic(0x00000000U, 0x00000000U, 0x00000000U, 0x00000000U);

Validate(
     VecAnyTrue_Word(testA) &&
     VecAnyTrue_Word(testB) &&
     VecAnyTrue_Word(testC) &&
    !VecAnyTrue_Word(testD)
);



SetFunctionName("VecAllTrue_Word");
using namespace ::rw::math::vpl;

VectorIntrinsic testA = CreateVectorIntrinsic(0x00000000U, 0xffffffffU, 0xffffffffU, 0x00000000U);
