VectorIntrinsic testC = CreateVectorIntrinsic(0xffffffffU, 0xffffffffU, 0xffffffffU, 0xffffffffU);
VectorIntrinsic testD = CreateVectorIntrinsic(0x00000000U, 0x00000000U, 0x00000000U, 0x00000000U);

Validate(
    !VecAllTrue_Word(testA) &&
    !VecAllTrue_Word(testB) &&
     VecAllTrue_Word(testC) &&
    !VecAllTrue_Word(testD)
);



