SetFunctionName("VecFloor");
using namespace ::rw::math::vpl;

VectorIntrinsic   v0 = CreateVectorIntrinsic(10.0f, 10.2f,  10.8f, 0.0f);
VectorIntrinsic ref0 = CreateVectorIntrinsic(10.0f, 10.0f,  10.0f, 0.0f);
VectorIntrinsic   v1 = CreateVectorIntrinsic(0.3f, -0.5f, -10.2f, -10.8f);
VectorIntrinsic ref1 = CreateVectorIntrinsic(0.0f, -1.0f, -11.0f, -11.0f);
VectorIntrinsic   v2 = CreateVectorIntrinsic(2.5521178e38f, -2.5521178e38f, 0.0f, 0.0f);
VectorIntrinsic ref2 = CreateVectorIntrinsic(2.5521178e38f, -2.5521178e38f, 0.0f, 0.0f);
VectorIntrinsic   r0 = VecFloor(v0);
VectorIntrinsic   r1 = VecFloor(v1);  
VectorIntrinsic   r2 = VecFloor(v2);
Validate(
    IsEqualFloat(r0, ref0) &&
    IsEqualFloat(r1, ref1) &&
    IsEqualFloat(r2, ref2)
);



