SetFunctionName("VecLoad");
using namespace ::rw::math::vpl;

VectorIntrinsic ref1 = CreateVectorIntrinsic(1.0f,  2.0f,  3.0f,  4.0f);
VectorIntrinsic ref2 = CreateVectorIntrinsic(5.0f,  6.0f,  7.0f,  8.0f);
VectorIntrinsic data[2];
data[0] = ref1;
data[1] = ref2;
VectorIntrinsic r1 = VecLoad( &data, 0 );
VectorIntrinsic r2 = VecLoad( &data, 16 );
Validate( IsEqualFloat(r1,ref1) &&
          IsEqualFloat(r2,ref2) );



SetFunctionName("VecStore");
using namespace ::rw::math::vpl;

VectorIntrinsic ref1 = CreateVectorIntrinsic(1.0f,  2.0f,  3.0f,  4.0f);
VectorIntrinsic ref2 = CreateVectorIntrinsic(5.0f,  6.0f,  7.0f,  8.0f);
VectorIntrinsic data[2];
VecStore( ref1, &data, 0 );
VecStore( ref2, &data, 16 );
Validate( IsEqualFloat(data[0],ref1) &&
          IsEqualFloat(data[1],ref2) );



SetFunctionName("VecLoadLeftAligned");
using namespace ::rw::math::vpl;

float floatData[8+4];
uintptr_t arrayAddress = reinterpret_cast<uintptr_t>(floatData);
float *floatPtr = reinterpret_cast<float*>( (arrayAddress + 15) & (~15) );
floatPtr[0] = 1.0f;
floatPtr[1] = 2.0f;
floatPtr[2] = 3.0f;
floatPtr[3] = 4.0f;
floatPtr[4] = 5.0f;
floatPtr[5] = 6.0f;
floatPtr[6] = 7.0f;
floatPtr[7] = 8.0f;
VectorIntrinsic ref0 = CreateVectorIntrinsic(1.0f,  2.0f,  3.0f,  4.0f);
VectorIntrinsic ref1 = CreateVectorIntrinsic(3.0f,  4.0f,  0.0f,  0.0f);
VectorIntrinsic ref2 = CreateVectorIntrinsic(3.0f,  4.0f,  0.0f,  0.0f);
VectorIntrinsic ref3 = CreateVectorIntrinsic(5.0f,  6.0f,  7.0f,  8.0f);
VectorIntrinsic   r0 = VecLoadLeftAligned( floatPtr, 0 );
VectorIntrinsic   r1 = VecLoadLeftAligned( floatPtr, 8 );
VectorIntrinsic   r2 = VecLoadLeftAligned( floatPtr+2, 0 );
VectorIntrinsic   r3 = VecLoadLeftAligned( floatPtr, 16 );
Validate( IsEqualFloat(r0,ref0) &&
          IsEqualFloat(r1,ref1) &&
          IsEqualFloat(r2,ref2) &&
          IsEqualFloat(r3,ref3) );



