SetFunctionName("VecStoreLeftAligned");
using namespace ::rw::math::vpl;

bool success = true;
float floatData[8+4];
uintptr_t arrayAddress = reinterpret_cast<uintptr_t>(floatData);
float *floatPtr = reinterpret_cast<float*>( (arrayAddress + 15) & (~15) );
float initialFloatValues[] = {1, 2, 3, 4, 5, 6, 7, 8};

for(int test=0;test<4;test++)
{
    float *address = 0;
    int offset = 0;
    VectorIntrinsic ref0 = CreateVectorIntrinsic(1.0f, 2.0f, 3.0f, 4.0f);
    VectorIntrinsic ref1 = CreateVectorIntrinsic(5.0f, 6.0f, 7.0f, 8.0f);
    VectorIntrinsic a = CreateVectorIntrinsic(10.0f, 20.0f, 30.0f, 40.0f);
    EA::StdC::Memcpy(floatPtr, initialFloatValues, sizeof(initialFloatValues));

    switch( test )
    {
    case 0:
        address = floatPtr;
        offset = 0;
        ref0 = CreateVectorIntrinsic(10.0f, 20.0f, 30.0f, 40.0f);
        break;
    case 1:
        address = floatPtr;
        offset = 8;
        ref0 = CreateVectorIntrinsic(1.0f, 2.0f, 10.0f, 20.0f);
        break;
    case 2:
        address = floatPtr+2;
        offset = 0;
        ref0 = CreateVectorIntrinsic(1.0f, 2.0f, 10.0f, 20.0f);
        break;
    case 3:
        address = floatPtr;
        offset = 16;
        ref1 = CreateVectorIntrinsic(10.0f, 20.0f, 30.0f, 40.0f);
        break;
    }
    VecStoreLeftAligned( a, address, offset );
    success &= IsEqualFloat( ref0, VecLoad(floatPtr, 0) );
    success &= IsEqualFloat( ref1, VecLoad(floatPtr, 16) );
}
Validate( success );



