for(int i=0;i<128;i++)
{
    alignedPtr[i] = (char)i;
}

MemCachePrefetch( alignedPtr - 17, 17 );

// Reliably testing for cache prefetching is difficult, since it is an optimization.
// This test only verifies that calling MemCachePrefetch doesn't modify the memory
// being prefetched.

bool success = true;
for(int i=0;i<128;i++)
{
    success &= (alignedPtr[i]==(char)i);
}
Validate(success);



SetFunctionName("MemCacheZero");
using namespace ::rw::math::vpl;

char buffer[256+128];
char *alignedPtr = (char *)((((uintptr_t)buffer)+127) & ~127);
for(int i=0;i<256+128;i++)
{
    buffer[i] = 'X';
}

MemCacheZero( alignedPtr - 17, 17 );


bool success = true;

// Make sure none of the memory before the first byte that is expected to be zero has been modified.
for(char *ptr=buffer;ptr!=alignedPtr;ptr++)
{
    success &= (*ptr=='X');
}

// Now count the number of zero bytes.
int zeroCount = 0;
while(*(alignedPtr++) == 0)
{
    zeroCount++;
}
#if defined EA_PLATFORM_XENON || defined EA_PLATFORM_PS3
    success &= ( zeroCount == 128 );
#elif defined EA_PLATFORM_REVOLUTION
    success &= ( zeroCount == 32 );
#else
    // Platform cache line sizes may vary, but these are the valid sizes for current platforms.
    success &= ( zeroCount == 0 || zeroCount == 32 || zeroCount == 64 || zeroCount == 128 );
#endif

Validate(success);



