SetFunctionName("VecUtilConvertFloatToHalf(VectorIntrinsic)");
using namespace ::rw::math::vpl;

/**
    float 0 10001110 11111111111111111111111 ( s(+) e(142) .... )                                 - 0x477FFFFF
    half  0 11110 1111111111 ( s(+) e(30) .... ) max positve half 65504 = 1 * 1.99 * 2^15  - 0x7BFF

    float 0 01110001 00000000000000000000000 ( s(+) e(113) .... )                                 - 0x38800000
    half  0 00001 0000000000 ( s(+) e(1) ....) min positve half = 1 * 1 * 2^-14                   - 0x0400

    float 1 01110001 00000000000000000000000 ( s(-) e(113) .... )                                  - 0xB8800000
    half  1 00001 0000000000 ( s(-) e(1) ....) max negative half = -1 * 1 * 2^-14                - 0x8400

    float 1 10001110 11111111111111111111111 ( s(-) e(142) ... )                                   - 0xC77FFFFF
    half  1 11110 1111111111 ( s(-) e(30) ....) min negative half -65504 = -1 * 1.99 * 2^15 - 0xFBFF

    float 0 00000000 00000000000000000000000 +0 - 0x00000000
    half  0 00000 0000000000 +0                             - 0x0000

    float 1 00000000 00000000000000000000000 -0  - 0x80000000
    half  1 00000 0000000000 -0                              - 0x8000

    VectorIntrinsic specialFloats = VecUtilCreateIntrinsic_UInt(0x7f800000, 0x80000001, 0x7f000000, 0x80800001);
    ::rw::math::vpl::VecUtilConvertFloatToHalf( specialFloats );

    VectorIntrinsic specialHalfs = VecUtilCreateIntrinsic_UInt(0x00007c00, 0x0000fc00, 0x00000001, 0x00000010);
    ::rw::math::vpl::VecUtilConvertHalfToFloat( specialHalfs );
**/
VectorIntrinsic halfValues = VecUtilCreateIntrinsic_UInt( 0xfbff, 0x7bff, 0x0400, 0x8400);
VectorIntrinsic floatValues = VecUtilCreateIntrinsic_UInt( 0xc77fffff, 0x477fffff, 0x38800000, 0xb8800000 );
VectorIntrinsic halfZerosNorms = VecUtilCreateIntrinsic_UInt( 0x0000, 0x8000, 0x220d, 0xca06 ); // e (0, 0, 8, 18) 8/18 = 120/130 - 127 + 15
VectorIntrinsic floatZerosNorms = VecUtilCreateIntrinsic_UInt( 0x00000000, 0x80000000, 0x3c41a8e9,  0xc140c800 ); // e (0, 0, 120, 130)

VectorIntrinsic resultHalf = ::rw::math::vpl::VecUtilConvertFloatToHalf( floatValues );
VectorIntrinsic resultHalfZerosNorms = ::rw::math::vpl::VecUtilConvertFloatToHalf( floatZerosNorms );

Validate( IsEqualBitwise(halfValues, resultHalf) &&
             IsEqualBitwise(halfZerosNorms, resultHalfZerosNorms)
             );



SetFunctionName("VecUtilConvertHalfToFloat(VectorIntrinsic)");
using namespace ::rw::math::vpl;

VectorIntrinsic halfValues = VecUtilCreateIntrinsic_UInt( 0xfbff, 0x7bff, 0x0400, 0x8400);
VectorIntrinsic floatValues = VecUtilCreateIntrinsic_UInt( 0xc77fe000, 0x477fe000, 0x38800000, 0xb8800000 );
VectorIntrinsic halfZerosNorms = VecUtilCreateIntrinsic_UInt( 0x0000, 0x8000, 0x3555, 0xca06 ); // e (0, 0, 13, 18) 0x3555 ~= 0.33325
VectorIntrinsic floatZerosNorms = VecUtilCreateIntrinsic_UInt( 0x00000000, 0x80000000, 0x3eaaa000,  0xc140c000 ); // e (0, 0, 125, 130)  125/130 = 13/18 - 15 + 127

VectorIntrinsic resultFloat = ::rw::math::vpl::VecUtilConvertHalfToFloat( halfValues );
VectorIntrinsic resultFloatZerosNorms = ::rw::math::vpl::VecUtilConvertHalfToFloat( halfZerosNorms );

Validate( IsEqualBitwise(floatValues, resultFloat) &&
             IsEqualBitwise(floatZerosNorms, resultFloatZerosNorms)
             );



