SetFunctionName("VecLoadImm_IntTest");

using namespace ::rw::math::vpl;

bool success = true;

{
    VectorIntrinsic ref = CreateVectorIntrinsicSignedInt(0, 0, 0, 0);
    VectorIntrinsic   r = VecLoadImm_Int<0>();
    success &= IsEqualBitwise(r,ref);
}

{
    VectorIntrinsic ref = CreateVectorIntrinsicSignedInt(-456789, -456789, -456789, -456789);
    VectorIntrinsic   r = VecLoadImm_Int<-456789>();
    success &= IsEqualBitwise(r,ref);
}
{
    VectorIntrinsic ref = CreateVectorIntrinsicSignedInt(987654, 987654, 987654, 987654);
    VectorIntrinsic   r = VecLoadImm_Int<987654>();
    success &= IsEqualBitwise(r,ref);
}

{
    VectorIntrinsic ref = CreateVectorIntrinsicSignedInt(-2147483647, -2147483647, -2147483647, -2147483647);
    VectorIntrinsic   r = VecLoadImm_Int<-2147483647>();
    success &= IsEqualBitwise(r,ref);
}
{
    VectorIntrinsic ref = CreateVectorIntrinsicSignedInt(2147483647, 2147483647, 2147483647, 2147483647);
    VectorIntrinsic   r = VecLoadImm_Int<2147483647>();
    success &= IsEqualBitwise(r,ref);
}
Validate(success);



